using System;using System.Collections.Generic;using System.Globalization;using System.Linq;using System.Windows.Forms;
namespace BeamScheduleFormatter {
class RoofProfile {public string Name,Family,SideLap;public double Width,Cover;}
partial class ProgramOfWorksForm {
 DataGridView roofProfiles;readonly List<RoofProfile> savedRoofProfiles=new List<RoofProfile>();
 void AddRoofProfiles(){roofProfiles=Grid(new[]{"Saved profile name","Family","Full sheet width mm","Side lap option","Effective cover mm","Status"},5);AddCombo(roofProfiles,1,"Family",new[]{"Longspan Rib","Longspan Corrugated"});roofProfiles.Columns[0].Width=230;roofProfiles.Columns[1].Width=210;roofProfiles.Columns[3].Width=160;roofProfiles.Rows.Add("Longspan Rib","Longspan Rib","1090","1 rib","1030");roofProfiles.Rows.Add("Longspan Rib","Longspan Rib","1090","2 ribs","750");roofProfiles.Rows.Add("Longspan Corrugated","Longspan Corrugated","1070","1-1/2","970");roofProfiles.Rows.Add("Longspan Corrugated","Longspan Corrugated","1070","2-1/2","890");AddGrid("Roofing Start",roofProfiles,"Save supplier profiles here. Repeat the profile name for each allowed side-lap option. Widths are in mm; effective cover already accounts for side lap. The supplied DN reference profiles are editable estimating presets. Choose a saved profile and side lap in the sheet worksheet.");}
 void RefreshRoofProfiles(){savedRoofProfiles.Clear();var seen=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(DataGridViewRow row in roofProfiles.Rows){if(row.IsNewRow||Empty(row))continue;try{var profile=new RoofProfile{Name=Cell(row,0),Family=Cell(row,1),Width=Number(row,2)/1000,SideLap=Cell(row,3),Cover=Number(row,4)/1000};RoofMath.Positive(profile.Width,profile.Cover);if(profile.Name==""||profile.SideLap==""||!new[]{"Longspan Rib","Longspan Corrugated"}.Contains(profile.Family)||profile.Cover>profile.Width)throw new Exception("Enter profile, family, side lap and cover <= full width.");if(!seen.Add(profile.Name+"|"+profile.SideLap))throw new Exception("Duplicate profile / side lap option.");if(savedRoofProfiles.Any(p=>string.Equals(p.Name,profile.Name,StringComparison.OrdinalIgnoreCase)&&(p.Family!=profile.Family||Math.Abs(p.Width-profile.Width)>1e-8)))throw new Exception("A profile name must have the same family and full width for all lap options.");savedRoofProfiles.Add(profile);row.Cells[5].Value="Saved in project";}catch(Exception ex){row.Cells[5].Value=ex.Message;errors.Add("Roof profile: "+ex.Message);}}
  var column=(DataGridViewComboBoxColumn)roofSheets.Columns[2];column.Items.Clear();column.Items.AddRange(savedRoofProfiles.Select(p=>p.Name).Distinct(StringComparer.OrdinalIgnoreCase).Cast<object>().ToArray());
 }
 void ApplyRoofProfile(DataGridViewRow row){row.Cells[8].Value="";row.Cells[9].Value="0";var options=savedRoofProfiles.Where(p=>string.Equals(p.Name,Cell(row,2),StringComparison.OrdinalIgnoreCase)).ToList();if(options.Count==0)throw new Exception("Choose a saved profile from Roofing Start.");string lap=Cell(row,17);if(!options.Any(p=>p.SideLap==lap)){string legacy=Cell(row,18);lap=options.Any(p=>p.SideLap==legacy)?legacy:options[0].SideLap;}var cell=(DataGridViewComboBoxCell)row.Cells[17];cell.Items.Clear();cell.Items.AddRange(options.Select(p=>p.SideLap).Cast<object>().ToArray());row.Cells[17].Value=lap;var profile=options.First(p=>p.SideLap==lap);row.Cells[6].Value=profile.Width.ToString("0.###",CultureInfo.InvariantCulture);row.Cells[7].Value=profile.Cover.ToString("0.###",CultureInfo.InvariantCulture);row.Cells[6].ReadOnly=row.Cells[7].ReadOnly=true;}
 string RoofFamily(DataGridViewRow row){var profile=savedRoofProfiles.FirstOrDefault(p=>string.Equals(p.Name,Cell(row,2),StringComparison.OrdinalIgnoreCase));return profile==null?Cell(row,2):profile.Family;}
}
}
